sp_widget.client_script:
api.controller = function($window) {
    /* widget controller */
    var c = this;

    // Clear browser storage to protect student privacy
    if ($window.localStorage) {
        $window.localStorage.clear();
    }
    if ($window.sessionStorage) {
        $window.sessionStorage.clear();
    }
};

sp_widget.css:
.vg-logout-page {
    min-height: 85vh;
    width: 100%;
    box-sizing: border-box;
    padding: 48px 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: "Segoe UI", Arial, sans-serif;
    color: #ffffff;
    background:
        radial-gradient(circle at 50% 0%, rgba(20, 145, 255, 0.22), transparent 28%),
        linear-gradient(135deg, #020817 0%, #061a35 48%, #020814 100%);
}

.vg-logout-shell {
    width: 100%;
    max-width: 520px;
    padding: 44px 38px 34px;
    box-sizing: border-box;
    text-align: center;
    border: 1px solid rgba(45, 149, 255, 0.28);
    border-radius: 18px;
    background: rgba(5, 19, 43, 0.86);
    box-shadow: 0 24px 70px rgba(0, 0, 0, 0.38);
    backdrop-filter: blur(14px);
}

.vg-logout-badge {
    width: 82px;
    height: 82px;
    margin: 0 auto 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(41, 210, 145, 0.65);
    border-radius: 50%;
    color: #25d891;
    background: rgba(37, 216, 145, 0.08);
}

.vg-logout-badge .glyphicon {
    font-size: 30px;
}

.vg-logout-shell h1 {
    margin: 0 0 12px;
    font-size: 32px;
    font-weight: 700;
    letter-spacing: 0;
    color: #f6f9ff;
}

.vg-logout-copy {
    max-width: 380px;
    margin: 0 auto 22px;
    color: #a9bad0;
    font-size: 15px;
    line-height: 1.7;
}

.vg-logout-status {
    width: fit-content;
    margin: 0 auto 28px;
    padding: 9px 14px;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: 1px solid rgba(37, 216, 145, 0.28);
    border-radius: 999px;
    color: #72e2b6;
    background: rgba(37, 216, 145, 0.08);
    font-size: 12px;
    font-weight: 700;
}

.vg-logout-actions {
    display: flex;
    gap: 12px;
    justify-content: center;
    margin-bottom: 24px;
}

.vg-primary-action,
.vg-secondary-action {
    min-width: 145px;
    height: 46px;
    padding: 0 18px;
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 700;
    text-decoration: none;
    transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.vg-primary-action {
    color: #ffffff;
    background: linear-gradient(90deg, #096fe9, #1556dc, #28a6d8);
    box-shadow: 0 10px 28px rgba(20, 108, 230, 0.25);
}

.vg-secondary-action {
    color: #c8d8ec;
    border: 1px solid rgba(144, 171, 205, 0.3);
    background: rgba(255, 255, 255, 0.04);
}

.vg-primary-action:hover,
.vg-secondary-action:hover {
    transform: translateY(-2px);
    text-decoration: none;
}

.vg-primary-action:hover {
    color: #ffffff;
    box-shadow: 0 14px 34px rgba(20, 108, 230, 0.36);
}

.vg-secondary-action:hover {
    color: #ffffff;
    background: rgba(255, 255, 255, 0.08);
}

.vg-logout-note {
    margin: 0;
    padding-top: 20px;
    border-top: 1px solid rgba(135, 162, 195, 0.14);
    color: #778aa3;
    font-size: 12px;
    line-height: 1.6;
}

@media (max-width: 560px) {
    .vg-logout-page {
        padding: 28px 14px;
    }

    .vg-logout-shell {
        padding: 34px 22px 28px;
    }

    .vg-logout-shell h1 {
        font-size: 26px;
    }

    .vg-logout-actions {
        flex-direction: column;
    }

    .vg-primary-action,
    .vg-secondary-action {
        width: 100%;
    }
}
